cd /workspace
python3 - <<'PY'
import random

def g(a,b,x):
    t=(a+b+x)&0xff
    return ((t<<2)|(t>>6))&0xff

def F(v):
    x=[(v>>(8*i))&0xff for i in range(4)]
    y=[0]*4
    y[2]=g(x[3]^x[2],x[1]^x[0],1)
    y[3]=g(x[3],y[2],0)
    y[1]=g(x[1]^x[0],y[2],0)
    y[0]=g(x[0],y[1],1)
    return sum(y[i]<<(8*i) for i in range(4))

# verify deterministic for deltas with only 0x80 in bytes
for mask in range(256):
    d=0
    for i in range(4):
        if mask>>i &1: d ^= 0x80<<(8*i)
    vals=set()
    for _ in range(20000):
        x=random.getrandbits(32)
        vals.add(F(x)^F(x^d))
        if len(vals)>1: break
    if len(vals)==1:
        print(f"{d:08x} -> {next(iter(vals)):08x}")
    else:
        print(f"{d:08x} -> NON deterministic {len(vals)}")
PY

